  "code": "def generated_builder(feature_cache, extra):\n    cost_a = feature_cache['cost_a']  # (N,)\n    cost_b = feature_cache['cost_b']  # (N,)\n    max_gap = float(extra.get('max_gap', 10.0))\n    gap = cost_b - cost_a  # (N,)\n    norm_gap = gap / max_gap\n    norm_gap = norm_gap.clamp(min=0.0)  # nonnegative linear weighting\n    epsilon = 1e-8\n    weight = norm_gap + epsilon\n    return PrefBatch(mode='pairwise', pair_idx=feature_cache['pair_idx'], weight=weight, meta={'weight_family': 'gap_linear'})"
