{
  "name": "gap_linear_reweight_fixed_v2",
  "intuition": "Compute nonnegative weights proportional to normalized cost gaps between paired items by indexing cost vectors with pair_idx, ensuring instance-local and stable linear weighting without Python loops.",
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    pair_idx = feature_cache['pair_idx']  # (P, 2) pairs\n    cost = feature_cache['cost']  # (N,) costs per instance\n    max_gap = float(extra.get('max_gap', 10.0))\n    cost_a = cost[pair_idx[:, 0]]  # (P,) costs of first items in pairs\n    cost_b = cost[pair_idx[:, 1]]  # (P,) costs of second items in pairs\n    gap = cost_b - cost_a  # (P,)\n    norm_gap = gap / max_gap\n    norm_gap = norm_gap.clamp(min=0.0)  # nonnegative linear weighting\n    epsilon = 1e-8\n    weight = norm_gap + epsilon\n    return PrefBatch(mode='pairwise', pair_idx=pair_idx, weight=weight, meta={'weight_family': 'gap_linear'})"
}
