{
  "name": "all_pairs_uniform_none",
  "intuition": "Construct all pairs with preference based on objective; assign uniform nonnegative weights without imports or complex computations to ensure stability and simplicity.",
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'uniform_none'})\n    weight_scale = float(extra.get('weight_scale', 1.0))\n    weight = weight_scale * weight_scale.new_ones(b_idx.shape, dtype=weight_scale.new_ones(1).dtype) if hasattr(weight_scale, 'new_ones') else weight_scale * objective.new_ones(b_idx.shape, dtype=objective.dtype)\n    weight = weight.to(dtype=objective.dtype)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'uniform_none'})"
}
