{
  "name": "pairwise_weight_builder",
  "intuition": "Constructs pairwise comparisons between all pairs within each batch, assigning a weight tensor that emphasizes pairs based on their feature difference magnitude, with a configurable scalar for flexibility. This supports reweighting the pre-existing all_pairs topology to focus on more or less confident pairings without altering the pair structure.",
  "hyperparams": {
    "geometry_family": "euclidean",
    "cap_family": "none",
    "weight_family": "gap_softmax",
    "constraint_family": "none"
  },
  "operators_used": ["pairwise_diff", "abs", "topk", "clamp", "mul", "zeros"],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    pair_idx = extra.get('pair_idx', None)\n    weight_scalar = float(extra.get('weight_scalar', 1.0))\n    scores = feature_cache['objective']\n    # Use pre-existing pairs\n    idx0, idx1 = pair_idx[1], pair_idx[2]\n    # Get pairs' feature differences\n    diffs = scores[0][idx0] - scores[0][idx1]\n    abs_diffs = ops.abs(diffs)\n    # Compute weights via softmax-like scaling\n    max_diff = ops.reduce_max(abs_diffs)\n    scaled = abs_diffs * weight_scalar\n    weights = ops.softmax(scaled)  # softmax over pairs\n    # Ensure nonnegativity\n    weights = ops.clamp(weights, min=0.0)\n    # Construct PrefBatch\n    return PrefBatch(mode='pairwise', pair_idx=pair_idx, weight=weights, meta={'method': 'pairwise_weight_builder'})"
}

