{
  "name": "uniform_weight_builder",
  "intuition": "Returns uniform, nonnegative weights for all pairs without relying on 'all_pairs' tensor in feature_cache, simplifying construction and avoiding missing keys while preserving fixed pair topology.",
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    # Use fixed pair topology from feature_cache if available, else assume pair_idx provided explicitly.
    pair_idx = feature_cache.get('pair_idx')
    if pair_idx is None:
        # Fallback: empty pair_idx to avoid crash, zero pairs
        pair_idx = ops.zeros((3, 0), dtype=ops.int64)
    else:
        pair_idx = pair_idx.astype(ops.int64)
    # Weight uniformly 1.0 for all pairs
    weight = ops.ones(pair_idx.shape[1], dtype=pair_idx.dtype)
    return PrefBatch(
        mode='pairwise',
        pair_idx=pair_idx,
        weight=weight,
        meta={'constructed_by': 'uniform_weight_builder'}
    )"
}
