{
  "name": "reweight_pairwise_gaps",
  "intuition": "Constructs pairs based on a fixed topology, keeping pairs from all_pairs, and applies a customizable non-negative weight function based on the cost gap difference scaled by an extra parameter, emphasizing pairs with larger cost differences. This leverages the pairing structure while allowing flexible reweighting for preference emphasis.",
  "hyperparams": {
    "geometry_family": "pairwise_linear",
    "cap_family": "none",
    "weight_family": "gap_linear",
    "constraint_family": "nonnegativity"
  },
  "operators_used": ["ops", "pairwise_ops", "masking", "topk"],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    pair_idx = feature_cache['pair_idx']  # Assume 'pair_idx' is provided as fixed template\n    cost_b = feature_cache['cost_b']\n    cost_a = feature_cache['cost_a']\n    diff = cost_b - cost_a  # shape (num_pairs,)\n    # Normalize extra parameters for weighting\n    tau = float(extra.get('weight_tau', 1.0))\n    # Compute weights as a linear scaled difference, ensuring non-negativity\n    weight = ops.clamp(tau * diff, min=0.0)\n    return PrefBatch(mode='pairwise', pair_idx=pair_idx, weight=weight, meta={'hyperparams': {'family': 'gap_linear'}})"
}

