{
  "name": "builder_all_pairs_uniform_none_reweighted",
  "intuition": "Only the pairwise weights are tuned to allow flexible reweighting while keeping the pair construction pattern fixed, aiming to better capture preferences under the reweighting mode. The weight values are computed with a configurable exponential decay based on cost gaps to emphasize significant pairs, with thresholds set to prevent overly small or large weights.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_exp",
    "constraint_family": "fixed_pair_reweight_only"
  },
  "operators_used": [
    "all_pairs",
    "mul",
    "exp",
    "max",
    "clamp"
  ],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap_values = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Configurable thresholds via extra\n    gap_threshold = float(extra.get('gap_threshold', 0.2))\n    weight_cap = float(extra.get('weight_cap', 10.0))\n    # Compute weights based on normalized gap\n    normalized_gap = gap_values / (1 + ops.abs(gap_values))\n    # Use exponential decay with configurable decay rate\n    decay_rate = float(extra.get('decay_rate', 1.0))\n    weights = ops.exp(-decay_rate * ops.clamp(normalized_gap - gap_threshold, min=0.0))\n    weights = ops.minimum(weights, weight_cap)\n    # Ensure weights are non-negative and finite\n    weights = ops.clamp(weights, 0.0, weight_cap)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_exp'})\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weights, meta={'builder': 'all_pairs', 'weight_family': 'gap_exp'})\n"
}

