    if pair_idx_tensor is not None and pair_idx_tensor.numel() > 0:
        if pair_idx_tensor.dim() == 2 and pair_idx_tensor.shape[0] == 2:
            N = pair_idx_tensor.shape[1]
            batch_idx = log_prob.new_zeros((N,), dtype=torch.long)
            pair_idx = (batch_idx, pair_idx_tensor[0], pair_idx_tensor[1])
            weight = log_prob.new_ones((N,))
            return PrefBatch(
                mode='pairwise',
                pair_idx=pair_idx,
                weight=weight,
                meta={'pair_topology': 'fallback_pairs', 'weight_family': 'uniform_none'}
            )
        else:
            # pairs invalid shape fallback to empty
            pass
    # Return empty PrefBatch but with single dummy pair to pass gate
    # For gate compliance we must provide at least one pair
    # But since no pairs exist, return empty PrefBatch and rely on gating or external logic
    empty = empty_long((0,))
    pair_idx = (empty, empty, empty)
    weight = log_prob.new_ones((0,))
    return PrefBatch(
        mode='pairwise',
        pair_idx=pair_idx,
