{
  "name": "reweight_gap_linear",
  "intuition": "Constructs preference pairs using all available pairs and assigns weights based on a linear function of the normalized cost gap, emphasizing pairs with larger cost differences to better reflect their importance in reweighting.",
  "hyperparams": {
