    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    all_pairs = feature_cache['all_pairs']  # precomputed fixed topology\n    objective = feature_cache['objective']  # shape (B,K)\n    pair_idx = all_pairs['pair_idx']  # shape (3, P)\n    cost_a = feature_cache['cost'][pair_idx[1]]  # shape (P,)\n    cost_b = feature_cache['cost'][pair_idx[2]]  # shape (P,)\n    # Use all pairs as per fixed template\n    log_prob = feature_cache['log_prob']  # shape (B,K)\n    lp_w = ops.gather(log_prob, pair_idx[1], axis=1)  # shape (B, P)\n    lp_l = ops.gather(log_prob, pair_idx[2], axis=1)  # shape (B, P)\n    # Compute normalized cost gap\n    cost_diff = cost_b - cost_a  # shape (P,)\n    norm_gap = (cost_diff - ops.mean(cost_diff)) / (ops.std(cost_diff) + 1e-6)  # shape (P,)\n    weight_scalar = extra.get('weight_tau', 1.0) * (norm_gap - ops.min(norm_gap)) / (ops.max(norm_gap) - ops.min(norm_gap) + 1e-6)\n    weight = weight_scalar  # vector of shape (P,)\n    return PrefBatch(mode='pairwise', pair_idx=pair_idx, weight=weight, meta={'family': 'gap_linear'})"
}

