  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    diff_objective = objective[b_idx, winner_idx] - objective[b_idx, loser_idx]\n    # Apply clipping to stabilize softmax\n    clipped_diff = ops.clip(diff_objective, a_min=-20.0, a_max=20.0)\n    # Compute weights via softmax to emphasize larger differences\n    weights = ops.softmax(clipped_diff, dim=0)\n    return PrefBatch(\n        mode='pairwise',\n        pair_idx=(b_idx.long(), winner_idx.long(), loser_idx.long()),\n        weight=weights,\n        meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax'}\n    )"
