{
  "name": "all_pairs_weighted_gap",
  "intuition": "Adjusts pair weights based on a normalized cost gap scaled by a configurable parameter, emphasizing pairs with larger normalized differences while ensuring non-negativity and stability within reweight-only mode.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
