  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Configurable parameters\n    weight_scale = float(extra.get('weight_scale', 1.0))\n    gap_threshold = float(extra.get('gap_threshold', 0.2))\n    # Normalize gap for stability and scaling\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    norm_gap = ops.clamp(gap / (gap_threshold + 1e-8), 0.0, 15.0)\n    # Compute weight: scaled by normalized gap, non-negative, stable\n    weight = ops.maximum(norm_gap * weight_scale, 0.0)\n    pair_idx = (b_idx, winner_idx, loser_idx)\n    return PrefBatch(mode='pairwise', pair_idx=pair_idx, weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})"
